INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '5. Jun. 2025', 'Die Saeima verschiebt die B2B-Pflicht vom 1. Jan. 2026 auf den 1. Jan. 2028' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'LV' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2026', 'Die verpflichtende Meldung von E-Rechnungsdaten an die VID beginnt (B2G/G2G/G2B)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'LV' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '30. Mär. 2026', 'Die freiwillige B2B-E-Rechnungsstellung und VID-Meldung wird über eAddress eröffnet' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'LV' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2028', 'Die B2B-E-Rechnungs- und VID-Datenmeldepflicht tritt in Kraft' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'LV' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Standard & Format', '[["Semantischer Standard", "EN 16931 -- umgesetzt als LVS EN 16931-1:2017 und LVS CEN/TS 16931-2:2017"], ["Maschinenlesbare Syntaxen", "UBL 2.1 und Peppol BIS Billing 3.0"], ["B2G-Übertragung", "Peppol-Zugangspunkte, gängige Praxis"], ["Künftige B2B-Übertragung (ab 2028)", "Kein einziges vorgeschriebenes Netz -- eAddress, ein zertifizierter Peppol-Zugangspunkt, oder der direkte bilaterale Austausch, jeweils gekoppelt mit einer gesonderten VID-Datenmeldepflicht"]]', 'Lettlands künftiges B2B-Regime versteht sich am besten als dezentrales E-Meldemodell, nicht als reines Peppol-Mandat -- Peppol ist ein zulässiger Übertragungsweg, nicht der vorgeschriebene.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Meldekanäle an die VID', '[["eAddress (e-adrese)", "Kostenlose nationale Plattform, betrieben von der Staatlichen Agentur für digitale Entwicklung (VDAA), leitet Daten automatisch an die VID weiter"], ["Zertifizierte Peppol-Zugangspunkte", "Mit einer VID-API verbunden"], ["Direkter Austausch + manuelle Meldung", "Bilateraler EDI-/E-Mail-/Software-Austausch ist zulässig, die Rechnungsdaten müssen jedoch gesondert innerhalb von 5 Werktagen an die VID gemeldet werden (über eAddress, eine Betreiber-API, oder das EDS der VID)"]]', 'Die Kabinettsverordnung Nr. 749 (erlassen am 9. Dez. 2025, in Kraft seit 1. Jan. 2026) regelt diese Verfahren im Detail -- ihr vollständiger Text konnte in dieser Rechercheeinheit nicht unabhängig über likumi.lv verifiziert werden, daher sollten die Einzelheiten als Sekundärzusammenfassung behandelt werden, die noch einer direkten Bestätigung bedarf.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer ist erfasst, und ab wann', '[["B2G/G2G/G2B (aktuell geltend)", "Alle in Lettland registrierten Unternehmen, die Haushalts-/Regierungsstellen beliefern"], ["B2B (ab 1. Jan. 2028)", "Alle in Lettland registrierten Unternehmen und Steuerpflichtigen, nur inländische Transaktionen -- grenzüberschreitendes B2B ist nicht erfasst"], ["Größenschwelle", "Keine bestätigt -- der stufenweise Zeitplan gibt kleineren Unternehmen mehr Vorbereitungszeit, statt eine dauerhafte Ausnahme darzustellen"], ["Ausnahmen", "Kassenbon-/Fiskalbeleg-Transaktionen, Transaktionen des Nationalen Gesundheitsdienstes, sowie bestimmte Behörden der nationalen Sicherheit (Staatssicherheitsdienst, Polizei, Steuerpolizei, KNAB)"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Die Verschiebung von 2025', '[["Ursprünglicher Plan", "Verpflichtende B2B-E-Rechnungsstellung ab 1. Januar 2026"], ["5. Juni 2025", "Die Saeima verabschiedet eine Änderung, die B2B auf den 1. Januar 2028 verschiebt, und lehnt einen konkurrierenden Vorschlag für 2027 ab"], ["Begründung", "Mehr Vorbereitungszeit für Steuerpflichtige, insbesondere Kleinunternehmen, sowie Zeit zur Aufrüstung der eAddress-Plattform"], ["30. März 2026", "Die freiwillige B2B-Phase wird als Zwischenschritt eröffnet"]]', 'Das eigene Länderdatenblatt der Europäischen Kommission zur E-Rechnungsstellung in Lettland zeigt mit Stand dieser Recherche weiterhin ein B2B-Datum vom 1. Januar 2026 -- es wurde seit der Verschiebung nicht aktualisiert. Behandeln Sie die aktuelleren, unabhängig bestätigten Quellen auf dieser Seite (einschließlich einer Aktualisierung vom 22. Juli 2026) als maßgeblicher als dieses Datenblatt in Bezug auf das B2B-Datum.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚠️ Noch kein eigener Bußgeldkatalog für die E-Rechnungsstellung veröffentlicht', NULL, NULL, 'Mit Stand dieser Recherche wurde in Lettland kein e-rechnungsspezifischer Bußgeldkatalog veröffentlicht -- dies wurde von mehreren Quellen ausdrücklich erklärt und ist nicht lediglich ein Fehlen in dem, was wir gefunden haben. Die praktische B2G-Folge heute ist, dass eine nicht konforme E-Rechnung von der empfangenden Regierungsstelle schlicht abgelehnt wird, wodurch die Zahlung blockiert wird, statt ein Bußgeld auszulösen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🧾 Allgemeiner Bußgeldrahmen des Buchhaltungsgesetzes (nur zur Einordnung)', NULL, NULL, 'Der allgemeine Bußgeldrahmen des Buchhaltungsgesetzes (eingeführt am 17. Okt. 2019, in Kraft seit 1. Jul. 2020, Bußgeldeinheit = 5 EUR) legt fest: bis zu 400 Einheiten (2.000 EUR) für unsachgemäße Buchführung oder Nichteinreichung von Berichten; bis zu 400 Einheiten (2.000 EUR) für Dokumentationsverstöße bei verbrauchsteuerpflichtigen Waren; bis zu 86 Einheiten (430 EUR) für sonstige Dokumentations-/Formatverstöße; bis zu 70 Einheiten (350 EUR) für Verstöße bei der Erfassung von Bargeschäften. Dies stammt aus der Zeit vor der E-Rechnungspflicht und ist ein allgemeiner Buchführungsrahmen, der wahrscheinlich analog angewendet würde -- kein bestätigtes, eigenständiges E-Rechnungsbußgeld.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'penalties_related' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie, dass Sie bereits strukturierte E-Rechnungen an lettische Regierungs-/Haushaltsstellen ausstellen', 'Verpflichtend seit dem 1. Januar 2025 -- bestätigen Sie, dass Ihre Rechnungen EN-16931-konform sind (UBL 2.1 oder Peppol BIS Billing 3.0), und nicht Papier oder einfaches PDF.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie, wie Ihre E-Rechnungsdaten die VID erreichen', 'Verpflichtend seit dem 1. Januar 2026 für B2G-/G2G-/G2B-Transaktionen -- über eAddress, einen zertifizierten Peppol-Zugangspunkt, oder die manuelle Einreichung über das Elektronische Deklarationssystem (EDS) der VID.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Erwägen Sie, sich jetzt der freiwilligen B2B-Phase anzuschließen, rechtzeitig vor der Frist 2028', 'Offen seit dem 30. März 2026 über eAddress -- die jetzige Nutzung erlaubt es Ihnen, Ihren Meldeprozess rechtzeitig vor dem verpflichtenden Termin am 1. Januar 2028 zu testen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Verlassen Sie sich für das B2B-Datum nicht auf das Länderdatenblatt der EU-Kommission zur E-Rechnungsstellung in Lettland', 'Es wurde seit der Verschiebung am 5. Juni 2025 nicht aktualisiert und zeigt weiterhin den 1. Januar 2026 -- nutzen Sie stattdessen die auf dieser Seite aufgeführten Quellen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Testen Sie Ihren gewählten B2B-Meldekanal rechtzeitig vor dem 1. Januar 2028', 'Derzeit gibt es keine bestätigte Übergangsfrist über dieses Datum hinaus, und die Frist wurde bereits einmal verschoben -- gehen Sie nicht von einer weiteren Verzögerung aus.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'eAddress (e-adrese) -- die nationale Plattform für den Austausch von E-Rechnungen/elektronischen Dokumenten' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'LV' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Elektronisches Deklarationssystem (EDS) der VID -- Meldung von E-Rechnungsdaten' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'LV' AND pt.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Länderdatenblatt der Europäischen Kommission zur E-Rechnungsstellung -- Lettland (Hinweis: das B2B-Datum wurde nach der Verschiebung noch nicht aktualisiert)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'LV' AND pt.sort_order = 2;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2g-central-2019', 'de',
  'B2G-E-Rechnungsstellung für zentrale Regierungsstellen verpflichtend',
  'Seit dem 18. April 2019 sind Lettlands Institutionen der direkten Verwaltung (zentrale Regierungsstellen) verpflichtet, strukturierte E-Rechnungen zu empfangen, gemäß der Kabinettsverordnung Nr. 154, die die EU-Richtlinie 2014/55/EU umsetzt.',
  '["Wenn Sie lettische zentrale Regierungsstellen beliefern, bestätigen Sie, dass Ihre Rechnungsstellung diese Anforderung bereits erfüllt."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2g-all-2020', 'de',
  'Die B2G-E-Rechnungsstellung wird auf alle öffentlichen Auftraggeber ausgeweitet',
  'Seit dem 18. April 2020 wurde die B2G-Empfangspflicht für E-Rechnungen von den zentralen Regierungsstellen auf alle übrigen lettischen öffentlichen Auftraggeber ausgeweitet und vervollständigte damit die anfängliche Umsetzung der EU-Richtlinie vor dem späteren nationalen E-Rechnungsgesetz.',
  '["Wenn Sie einen beliebigen lettischen öffentlichen Auftraggeber beliefern, bestätigen Sie, dass Ihre E-Rechnungsabdeckung über die zentrale Regierung hinausgeht."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2g-issuance-2025', 'de',
  'B2G-Pflicht: Alle Unternehmen müssen strukturierte E-Rechnungen an die Regierung ausstellen',
  'Seit dem 1. Januar 2025 verpflichten Änderungen des lettischen Buchhaltungsgesetzes (Gramatvedibas likums) alle in Lettland registrierten Unternehmen, strukturierte E-Rechnungen -- im Format EN 16931 (LVS EN 16931-1:2017) -- an Haushalts- und Regierungsstellen (B2G/G2G) auszustellen, ausgetauscht über die kostenlose nationale Plattform eAddress (e-adrese), einen zertifizierten Peppol-Zugangspunkt, oder einen anderen mit der VID verbundenen Kanal.',
  '["Bestätigen Sie, dass Ihr Unternehmen strukturierte, EN-16931-konforme E-Rechnungen an jede lettische Regierungs- oder Haushaltsinstitutions-Gegenpartei ausstellt, nicht Papier oder einfaches PDF.","Registrieren Sie sich für eAddress (über www.latvija.gov.lv, mit Smart-ID, eID oder eParaksts), falls noch nicht geschehen."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2b-postponed-2025', 'de',
  'Die Saeima verschiebt die B2B-Pflicht von 2026 auf 2028',
  'Am 5. Juni 2025 verabschiedete die Saeima (das lettische Parlament) Änderungen, die den verpflichtenden Start der B2B-E-Rechnungsstellung/E-Meldung vom ursprünglich geplanten 1. Januar 2026 auf den 1. Januar 2028 verschieben -- und lehnte damit einen konkurrierenden Vorschlag für ein Zwischendatum 2027 zugunsten eines längeren Vorlaufs plus einer freiwilligen Zwischenphase ab. Als Begründung wurde angegeben, Steuerpflichtigen, insbesondere Kleinunternehmen, mehr Vorbereitungszeit zu geben und zunächst die eAddress-Plattform aufzurüsten.',
  '["Planen Sie nicht mit einer B2B-E-Rechnungsfrist vom 1. Januar 2026 für Lettland -- dieses Datum wurde auf den 1. Januar 2028 verschoben.","Beachten Sie, dass einige Sekundärquellen und das eigene Länderdatenblatt der EU-Kommission möglicherweise weiterhin auf das überholte Datum 2026 verweisen -- prüfen Sie dies anhand der auf dieser Seite aufgeführten Quellen."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-vid-reporting-2026', 'de',
  'Die verpflichtende Meldung von E-Rechnungsdaten an die VID beginnt',
  'Seit dem 1. Januar 2026 macht die Kabinettsverordnung Nr. 749 (erlassen am 9. Dezember 2025) die Meldung strukturierter E-Rechnungsdaten an die Staatliche Steuerbehörde (VID) für B2G-/G2G-/G2B-Transaktionen verpflichtend, über eAddress, einen zertifizierten Peppol-Zugangspunkt mit VID-API-Anbindung, oder den manuellen Upload über das Elektronische Deklarationssystem (EDS) der VID. Hinweis: Der vollständige Text dieser Verordnung konnte in dieser Rechercheeinheit nicht unabhängig über likumi.lv verifiziert werden -- bestätigt wurde er nur über eine Sekundärzusammenfassung.',
  '["Bestätigen Sie, wie Ihre B2G-/G2G-E-Rechnungsdaten die VID erreichen -- über eAddress, einen Peppol-Zugangspunkt, oder die manuelle EDS-Einreichung.","Überprüfen Sie die genauen Anforderungen der Kabinettsverordnung Nr. 749 unabhängig über likumi.lv, bevor Sie Ihren Meldeprozess festlegen."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2b-voluntary-2026', 'de',
  'Die freiwillige B2B-E-Rechnungsstellung und VID-Meldung wird eröffnet',
  'Seit dem 30. März 2026 können lettische Unternehmen freiwillig beginnen, strukturierte B2B-E-Rechnungen auszustellen und die Daten über eAddress an die VID zu melden, vor dem verpflichtenden Termin am 1. Januar 2028 -- ein Zwischenschritt, der in die Verschiebung vom 5. Juni 2025 eingebaut wurde, damit sich Plattform und Unternehmen schrittweise vorbereiten können, statt vor einer abrupten Umstellung zu stehen.',
  '["Erwägen Sie, sich jetzt der freiwilligen B2B-E-Rechnungs-/Meldephase über eAddress anzuschließen, um Ihren Prozess rechtzeitig vor dem verpflichtenden Termin 2028 zu testen."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2b-mandatory-2028', 'de',
  'Die verpflichtende B2B-E-Rechnungsstellung und VID-Meldung beginnt',
  'Seit dem 1. Januar 2028 müssen alle in Lettland registrierten Unternehmen und Steuerpflichtigen strukturierte, EN-16931-konforme E-Rechnungen für inländische B2B-Transaktionen ausstellen und melden -- über eAddress, einen zertifizierten Peppol-Zugangspunkt, oder den direkten bilateralen Austausch gekoppelt mit einer gesonderten VID-Datenmeldung innerhalb von 5 Werktagen. Grenzüberschreitende B2B-Rechnungen sind von dieser inländischen Pflicht nicht erfasst. Mit Stand dieser Recherche wurde kein eigener Bußgeldkatalog für die E-Rechnungsstellung veröffentlicht; die praktische Folge nicht konformer B2G-Rechnungen ist heute die Ablehnung durch die empfangende Regierungsstelle, nicht ein Bußgeld.',
  '["Bestätigen Sie, dass Ihre Rechnungssoftware EN-16931-konforme E-Rechnungen erzeugen kann (UBL 2.1 oder Peppol BIS Billing 3.0).","Wählen und testen Sie einen Meldekanal an die VID -- eAddress, einen Peppol-Zugangspunkt, oder EDS -- rechtzeitig vor dem 1. Januar 2028.","Nutzen Sie die freiwillige Phase (offen seit dem 30. März 2026), um Ihren Prozess vor dem verpflichtenden Termin zu testen."]'
);

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr',
  'Régime progressif : une obligation B2G de facturation électronique déjà en vigueur depuis 2025, complétée par la déclaration obligatoire des données à la VID depuis 2026, passant par une phase B2B volontaire avant une obligation B2B obligatoire confirmée pour le 1er janvier 2028 -- reportée par rapport à une date initialement prévue en 2026',
  'Cette page d''analyse reflète les modifications apportées à la loi comptable lettone (Gramatvedibas likums), au règlement du Cabinet n° 749, ainsi que les indications publiques du Service national des impôts (VID) disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences actuelles directement auprès de la VID, de l''Agence nationale du développement numérique, ou d''un conseiller fiscal/juridique letton avant de fonder vos décisions de conformité sur cette page.',
  'L''obligation de facturation électronique B2G en Lettonie a débuté avec la transposition de la directive de l''UE : les organismes du gouvernement central à partir du 18 avril 2019, puis toutes les entités adjudicatrices à partir du 18 avril 2020. Le droit national a ensuite étendu cette obligation : depuis le 1er janvier 2025, toutes les entreprises immatriculées en Lettonie doivent émettre des factures électroniques structurées à destination des entités publiques/budgétaires. Une obligation B2B initialement prévue pour le 1er janvier 2026 a été reportée par la Saeima le 5 juin 2025 au 1er janvier 2028, avec deux étapes intermédiaires : la déclaration obligatoire des données de factures électroniques à la VID pour les transactions B2G/G2G/G2B à partir du 1er janvier 2026, et une phase B2B volontaire de facturation électronique/déclaration ouverte depuis le 30 mars 2026.',
  'La norme sémantique est EN 16931 (mise en œuvre en Lettonie sous les références LVS EN 16931-1:2017 et LVS CEN/TS 16931-2:2017), exprimée en XML UBL 2.1 ou Peppol BIS Billing 3.0. Pour le B2G, les points d''accès Peppol constituent la pratique standard. Pour la future obligation B2B, la Lettonie ne désigne pas de réseau de transmission unique et obligatoire : les factures électroniques structurées peuvent transiter via la plateforme nationale gratuite eAddress (e-adrese), un point d''accès Peppol certifié intégré à une API de la VID, ou l''échange bilatéral direct (EDI, courriel, logiciel à logiciel) -- mais l''échange direct comporte une obligation distincte de déclarer les données de la facture à la VID dans un délai de 5 jours ouvrables. Cela fait du modèle B2B letton un régime décentralisé de déclaration électronique, et non une obligation « tout envoyer via Peppol ».',
  'L''obligation B2G/G2G/G2B déjà en vigueur couvre toutes les entreprises immatriculées en Lettonie qui fournissent des institutions budgétaires ou publiques. La future obligation B2B (à partir du 1er janvier 2028) couvre toutes les entreprises et personnes assujetties immatriculées en Lettonie, uniquement pour les transactions nationales -- les factures B2B transfrontalières ne sont pas couvertes. Aucune exonération permanente confirmée fondée sur le chiffre d''affaires ou la taille des petites entreprises n''a été trouvée ; le calendrier progressif 2026-2028 est explicitement présenté comme laissant davantage de temps de préparation aux petites entreprises, et non comme une exclusion fondée sur un seuil. Les exonérations confirmées comprennent les opérations réalisées par caisse enregistreuse/reçu fiscal, les opérations du Service national de santé, et certains organismes de sécurité nationale (le Service de sécurité de l''État, la Police, la Police fiscale et le Bureau de lutte contre la corruption/KNAB).',
  'Si vous fournissez des entités publiques ou budgétaires lettonnes, les obligations déjà en vigueur (facturation électronique B2G depuis 2025, déclaration des données à la VID depuis 2026) s''appliquent dès maintenant. Pour le commerce B2B au sein de la Lettonie, il n''existe actuellement aucune obligation -- le travail à accomplir consiste à utiliser la phase volontaire (ouverte depuis le 30 mars 2026) pour préparer un canal de déclaration bien avant l''échéance obligatoire du 1er janvier 2028, plutôt que d''attendre une échéance déjà repoussée une fois.',
  'Aucun barème de sanctions spécifique à la facturation électronique n''a été publié en Lettonie à la date de cette recherche. La conséquence pratique aujourd''hui pour une facture B2G non conforme est le rejet par l''entité publique destinataire (ce qui bloque le paiement), et non une amende. Les sanctions générales de la loi comptable existent en tant que cadre plus large susceptible de s''appliquer par analogie aux manquements en matière de comptabilité/documentation, mais aucune source ne rattache un montant en euros précis directement à la non-conformité en matière de facturation électronique.',
  'La Lettonie impose la facturation électronique B2G depuis le 1er janvier 2025 et la déclaration obligatoire des données de factures électroniques à la VID pour les transactions B2G/G2G/G2B depuis le 1er janvier 2026. Une phase volontaire de facturation électronique et de déclaration B2B à la VID est ouverte depuis le 30 mars 2026, via la plateforme nationale gratuite eAddress, avant une obligation B2B obligatoire confirmée pour le 1er janvier 2028 -- reportée par la Saeima le 5 juin 2025 par rapport à une date initialement prévue au 1er janvier 2026. Aucun barème de sanctions spécifique à la facturation électronique n''a encore été publié.',
  '🇱🇻'
FROM countries WHERE code = 'LV';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2025', 'Facturation électronique B2G : toutes les entreprises doivent émettre des factures électroniques structurées à destination du gouvernement' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'LV' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '5 juin 2025', 'La Saeima reporte l''obligation B2B du 1er janv. 2026 au 1er janv. 2028' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'LV' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2026', 'Début de la déclaration obligatoire des données de factures électroniques à la VID (B2G/G2G/G2B)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'LV' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '30 mars 2026', 'Ouverture de la facturation électronique et de la déclaration B2B volontaire via eAddress' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'LV' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2028', 'Entrée en vigueur de l''obligation de facturation électronique et de déclaration de données B2B à la VID' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'LV' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Norme et format', '[["Norme sémantique", "EN 16931 -- mise en œuvre sous les références LVS EN 16931-1:2017 et LVS CEN/TS 16931-2:2017"], ["Syntaxes lisibles par machine", "UBL 2.1 et Peppol BIS Billing 3.0"], ["Transport B2G", "Points d''accès Peppol, pratique standard"], ["Futur transport B2B (à partir de 2028)", "Aucun réseau unique imposé -- eAddress, un point d''accès Peppol certifié, ou l''échange bilatéral direct, chacun accompagné d''une obligation distincte de déclaration de données à la VID"]]', 'Le futur régime B2B letton se comprend mieux comme un modèle décentralisé de déclaration électronique, et non comme une obligation Peppol pure -- Peppol est un mode de transport autorisé, et non le mode imposé.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Canaux de déclaration à la VID', '[["eAddress (e-adrese)", "Plateforme nationale gratuite, exploitée par l''Agence nationale du développement numérique (VDAA), qui transmet automatiquement les données à la VID"], ["Points d''accès Peppol certifiés", "Intégrés à une API de la VID"], ["Échange direct + déclaration manuelle", "L''échange bilatéral par EDI/courriel/logiciel est autorisé, mais les données de la facture doivent être déclarées séparément à la VID (via eAddress, une API d''opérateur, ou l''EDS de la VID) dans un délai de 5 jours ouvrables"]]', 'Le règlement du Cabinet n° 749 (adopté le 9 déc. 2025, en vigueur depuis le 1er janv. 2026) fixe ces procédures en détail -- son texte intégral n''a pas pu être vérifié de manière indépendante via likumi.lv au cours de cette session de recherche ; ces détails doivent donc être traités comme un résumé secondaire en attente de confirmation directe.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui est couvert, et à partir de quand', '[["B2G/G2G/G2B (en vigueur)", "Toutes les entreprises immatriculées en Lettonie qui fournissent des institutions budgétaires/publiques"], ["B2B (à partir du 1er janv. 2028)", "Toutes les entreprises et personnes assujetties immatriculées en Lettonie, transactions nationales uniquement -- le B2B transfrontalier n''est pas couvert"], ["Seuil de taille", "Aucun confirmé -- le calendrier progressif laisse aux petites entreprises davantage de temps de préparation plutôt que de constituer une exonération permanente"], ["Exonérations", "Opérations par caisse enregistreuse/reçu fiscal, opérations du Service national de santé, et certains organismes de sécurité nationale (Service de sécurité de l''État, Police, Police fiscale, KNAB)"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Le report de 2025', '[["Plan initial", "Facturation électronique B2B obligatoire à partir du 1er janvier 2026"], ["5 juin 2025", "La Saeima adopte un amendement reportant le B2B au 1er janvier 2028, rejetant une proposition concurrente pour 2027"], ["Justification", "Davantage de temps de préparation pour les contribuables, en particulier les petites entreprises, et du temps pour mettre à niveau la plateforme eAddress"], ["30 mars 2026", "La phase B2B volontaire s''ouvre comme étape intermédiaire"]]', 'La fiche pays de la Commission européenne relative à la facturation électronique en Lettonie affiche toujours, à la date de cette recherche, une date B2B du 1er janvier 2026 -- elle n''a pas été mise à jour depuis le report. Considérez les sources plus récentes et corroborées de manière indépendante figurant sur cette page (y compris une mise à jour du 22 juillet 2026) comme faisant davantage autorité que cette fiche pour la date B2B.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚠️ Aucune sanction spécifique à la facturation électronique encore publiée', NULL, NULL, 'Aucun barème d''amendes spécifique à la facturation électronique n''a été publié en Lettonie à la date de cette recherche -- cela a été indiqué explicitement par plusieurs sources, et non simplement constaté comme absent de ce que nous avons trouvé. La conséquence pratique B2G aujourd''hui est qu''une facture électronique non conforme est simplement rejetée par l''entité publique destinataire, ce qui bloque le paiement, plutôt que de déclencher une amende monétaire.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🧾 Cadre général de sanctions de la loi comptable (contexte uniquement)', NULL, NULL, 'Le cadre général de sanctions de la loi comptable (ajouté le 17 oct. 2019, en vigueur depuis le 1er juil. 2020, unité de sanction = 5 EUR) prévoit : jusqu''à 400 unités (2 000 EUR) pour tenue de registres inappropriée ou non-soumission de rapports ; jusqu''à 400 unités (2 000 EUR) pour infractions à la documentation des produits soumis à accise ; jusqu''à 86 unités (430 EUR) pour d''autres infractions de documentation/format ; jusqu''à 70 unités (350 EUR) pour infractions relatives à l''enregistrement des opérations en espèces. Ce cadre est antérieur à l''obligation de facturation électronique et constitue un cadre comptable général susceptible de s''appliquer par analogie -- et non une amende confirmée et spécifique à la facturation électronique.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'LV' AND cd.section = 'penalties_related' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que vous émettez déjà des factures électroniques structurées à destination des entités publiques/budgétaires lettonnes', 'Obligatoire depuis le 1er janvier 2025 -- vérifiez que vos factures sont conformes à EN 16931 (UBL 2.1 ou Peppol BIS Billing 3.0), et non sur papier ou en simple PDF.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez comment vos données de facturation électronique parviennent à la VID', 'Obligatoire depuis le 1er janvier 2026 pour les transactions B2G/G2G/G2B -- via eAddress, un point d''accès Peppol certifié, ou la soumission manuelle via le Système de déclaration électronique (EDS) de la VID.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Envisagez d''adhérer dès maintenant à la phase B2B volontaire, avant l''échéance de 2028', 'Ouverte depuis le 30 mars 2026 via eAddress -- l''utiliser dès maintenant vous permet de tester votre processus de déclaration bien avant l''échéance obligatoire du 1er janvier 2028.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Ne vous fiez pas à la fiche pays de la Commission européenne relative à la facturation électronique en Lettonie pour la date B2B', 'Elle n''a pas été mise à jour depuis le report du 5 juin 2025 et affiche toujours le 1er janvier 2026 -- utilisez plutôt les sources indiquées sur cette page.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Testez le canal de déclaration B2B choisi bien avant le 1er janvier 2028', 'Il n''existe actuellement aucune période de grâce confirmée au-delà de cette date, et l''échéance a déjà été repoussée une fois -- ne présumez pas d''un nouveau report.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'LV' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'eAddress (e-adrese) -- la plateforme nationale d''échange de factures électroniques/documents électroniques' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'LV' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Système de déclaration électronique (EDS) de la VID -- déclaration des données de factures électroniques' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'LV' AND pt.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Fiche pays de la Commission européenne relative à la facturation électronique -- Lettonie (remarque : la date B2B n''a pas encore été mise à jour après le report)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'LV' AND pt.sort_order = 2;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2g-central-2019', 'fr',
  'Facturation électronique B2G obligatoire pour les organismes du gouvernement central',
  'Depuis le 18 avril 2019, les institutions d''administration directe de la Lettonie (organismes du gouvernement central) sont tenues de recevoir des factures électroniques structurées, en vertu du règlement du Cabinet n° 154, transposant la directive 2014/55/UE de l''UE.',
  '["Si vous fournissez des organismes du gouvernement central letton, vérifiez que votre facturation répond déjà à cette exigence."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2g-all-2020', 'fr',
  'La facturation électronique B2G s''étend à toutes les entités adjudicatrices',
  'Depuis le 18 avril 2020, l''obligation de réception des factures électroniques B2G s''est étendue des organismes du gouvernement central à toutes les autres entités adjudicatrices lettonnes, achevant le déploiement initial de la directive de l''UE avant l''adoption ultérieure de la loi nationale sur la facturation électronique.',
  '["Si vous fournissez une entité adjudicatrice publique lettonne, vérifiez que votre couverture de facturation électronique s''étend au-delà du seul gouvernement central."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2g-issuance-2025', 'fr',
  'Obligation B2G : toutes les entreprises doivent émettre des factures électroniques structurées à destination du gouvernement',
  'Depuis le 1er janvier 2025, les modifications apportées à la loi comptable lettone (Gramatvedibas likums) exigent que toutes les entreprises immatriculées en Lettonie émettent des factures électroniques structurées -- au format EN 16931 (LVS EN 16931-1:2017) -- à destination des entités budgétaires et publiques (B2G/G2G), échangées via la plateforme nationale gratuite eAddress (e-adrese), un point d''accès Peppol certifié, ou un autre canal intégré à la VID.',
  '["Vérifiez que votre entreprise émet des factures électroniques structurées, conformes à EN 16931, à destination de toute contrepartie publique ou d''institution budgétaire lettonne, et non sur papier ou en simple PDF.","Inscrivez-vous à eAddress (via www.latvija.gov.lv, au moyen de Smart-ID, eID ou eParaksts) si ce n''est pas déjà fait."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2b-postponed-2025', 'fr',
  'La Saeima reporte l''obligation B2B de 2026 à 2028',
  'Le 5 juin 2025, la Saeima (le Parlement letton) a adopté des amendements reportant l''entrée en vigueur obligatoire de la facturation/déclaration électronique B2B de la date initialement prévue du 1er janvier 2026 au 1er janvier 2028 -- rejetant une proposition concurrente pour une date intermédiaire en 2027, au profit d''un délai plus long assorti d''une phase volontaire intermédiaire. La justification avancée était de laisser aux contribuables, en particulier aux petites entreprises, davantage de temps de préparation, et de permettre au préalable la mise à niveau de la plateforme eAddress.',
  '["Ne planifiez pas en fonction d''une échéance du 1er janvier 2026 pour la facturation électronique B2B en Lettonie -- cette date a été reportée au 1er janvier 2028.","Notez que certaines sources secondaires et la fiche pays de la Commission européenne elle-même peuvent encore faire référence à la date de 2026, désormais caduque -- vérifiez auprès des sources indiquées sur cette page."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-vid-reporting-2026', 'fr',
  'Début de la déclaration obligatoire des données de factures électroniques à la VID',
  'Depuis le 1er janvier 2026, le règlement du Cabinet n° 749 (adopté le 9 décembre 2025) rend obligatoire la déclaration des données de factures électroniques structurées au Service national des impôts (VID) pour les transactions B2G/G2G/G2B, via eAddress, un point d''accès Peppol certifié doté d''une intégration API avec la VID, ou le téléversement manuel via le Système de déclaration électronique (EDS) de la VID. Remarque : le texte intégral de ce règlement n''a pas pu être vérifié de manière indépendante via likumi.lv au cours de cette session de recherche -- il n''a été confirmé que par un résumé secondaire.',
  '["Vérifiez comment vos données de facturation électronique B2G/G2G parviennent à la VID -- via eAddress, un point d''accès Peppol, ou la soumission manuelle via l''EDS.","Vérifiez de manière indépendante les exigences exactes du règlement du Cabinet n° 749 via likumi.lv avant de finaliser votre processus de déclaration."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2b-voluntary-2026', 'fr',
  'Ouverture de la facturation électronique et de la déclaration B2B volontaire à la VID',
  'Depuis le 30 mars 2026, les entreprises lettonnes peuvent commencer volontairement à émettre des factures électroniques B2B structurées et à déclarer les données à la VID via eAddress, avant l''échéance obligatoire du 1er janvier 2028 -- une étape intermédiaire intégrée au report du 5 juin 2025 pour permettre à la plateforme et aux entreprises de se préparer progressivement plutôt que de faire face à une transition brutale.',
  '["Envisagez d''adhérer dès maintenant à la phase volontaire de facturation électronique/déclaration B2B via eAddress, afin de tester votre processus bien avant l''échéance obligatoire de 2028."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'lv-b2b-mandatory-2028', 'fr',
  'Début de la facturation électronique et de la déclaration B2B obligatoire à la VID',
  'Depuis le 1er janvier 2028, toutes les entreprises et personnes assujetties immatriculées en Lettonie doivent émettre et déclarer des factures électroniques structurées, conformes à EN 16931, pour les transactions B2B nationales -- via eAddress, un point d''accès Peppol certifié, ou l''échange bilatéral direct assorti d''une déclaration de données distincte à la VID dans un délai de 5 jours ouvrables. Les factures B2B transfrontalières ne sont pas couvertes par cette obligation nationale. Aucun barème de sanctions spécifique à la facturation électronique n''a été publié à la date de cette recherche ; la conséquence pratique aujourd''hui pour les factures B2G non conformes est le rejet par l''entité publique destinataire, et non une amende monétaire.',
  '["Vérifiez que votre logiciel de facturation peut produire des factures électroniques conformes à EN 16931 (UBL 2.1 ou Peppol BIS Billing 3.0).","Choisissez et testez un canal de déclaration à la VID -- eAddress, un point d''accès Peppol, ou l''EDS -- bien avant le 1er janvier 2028.","Utilisez la phase volontaire (ouverte depuis le 30 mars 2026) pour tester votre processus avant l''échéance obligatoire."]'
);
